package com.movrit.movrit.collaboration.dto;
import com.movrit.movrit.collaboration.entity.*; import jakarta.validation.constraints.*; import java.time.LocalDateTime;
public final class CollaborationDtos {private CollaborationDtos(){}
 public record CampaignRequest(@NotNull Long preorderId,@NotBlank String title,String description,String category,@NotNull @Min(0)Long minFollowerCount,@NotNull @Min(1)Integer recruitmentCount,String rewardDescription,@NotNull LocalDateTime startAt,@NotNull LocalDateTime endAt){}
 public record CampaignResponse(Long id,Long preorderId,String preorderTitle,String brandName,String title,String description,String category,Long minFollowerCount,Integer recruitmentCount,String rewardDescription,LocalDateTime startAt,LocalDateTime endAt,boolean open){public static CampaignResponse from(Campaign c){return new CampaignResponse(c.getId(),c.getPreorder().getId(),c.getPreorder().getTitle(),c.getPreorder().getProduct().getBrand().getName(),c.getTitle(),c.getDescription(),c.getCategory(),c.getMinFollowerCount(),c.getRecruitmentCount(),c.getRewardDescription(),c.getStartAt(),c.getEndAt(),c.isOpen());}}
 public record ApplyRequest(@NotBlank String message){} public record ProposeRequest(@NotNull Long preorderId,@NotNull Long creatorId,@NotBlank String message){}
 public record Response(Long id,Long preorderId,String preorderTitle,Long creatorId,String creatorNickname,CollaborationType type,CollaborationStatus status,String message,String referralCode,String referralUrl){public static Response from(Collaboration c){String url=c.getReferralCode()==null?null:"/preorders/"+c.getPreorder().getId()+"?ref="+c.getReferralCode();return new Response(c.getId(),c.getPreorder().getId(),c.getPreorder().getTitle(),c.getCreator().getId(),c.getCreator().getNickname(),c.getType(),c.getStatus(),c.getMessage(),c.getReferralCode(),url);}}
}
